/**
 * A line chart for change over time (`design/components/line-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/line-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  DEFAULT_RANGE_MESSAGES,
  Each,
  Icon,
  UNMEASURED,
  agentMember,
  brushChartRange,
  brushDrawing,
  brushSpan,
  brushValues,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartRange,
  chartSeries,
  chooseChartMark,
  claimSlot,
  createBrush,
  createCell,
  createDerived,
  createReading,
  createSyncMember,
  createWarningLog,
  devWarning,
  elementRef,
  lineChartModel,
  lineChartReadout,
  lineChartSelection,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  scope,
  syncIndexOf,
  syncValueAt,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartAnnotation,
  type ChartBaseline,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/charts/line-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartBrush from '@polymorph/recipes/charts/frame/chart-brush.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button'
import Table from '../structure/Table'
import TableBody from '../structure/TableBody'
import TableCell from '../structure/TableCell'
import TableHead from '../structure/TableHead'
import TableHeader from '../structure/TableHeader'
import TableRow from '../structure/TableRow'

export interface LineChartProps {
  /**
   * Annotations from the closed union above: line, band and point, literals only. The frame's
   * shared annotation layer draws them in `--pm-chart-axis`, with bands washed in
   * `--pm-chart-other` at 0.08. An annotation never re-centres colour. Colliding labels are
   * dropped, but the annotation itself always draws because the app asked for it explicitly.
   */
  annotations?: readonly ChartAnnotation[]
  baseline?: ChartBaseline
  /**
   * The line shape. `step` is **`curveStepAfter`**: a measurement holds until the next one.
   * `'linear'` is engine-internal and not offered here.
   */
  curve?: 'monotone' | 'step'
  /**
   * The data rows. `[]` renders the built-in empty state.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Key of the series to emphasise. It keeps its slot colour and the rest use
   * `--pm-chart-other`. A status-toned series keeps its status colour, because reserved meaning
   * is never greyed out.
   */
  emphasis?: string
  /**
   * The chart's accessible name. It is required, as for Progress, because an unnamed chart tells
   * a reader nothing.
   */
  label: string
  /**
   * Loading state. On first render the frame shows a quiet `Skeleton`; on refetch it shows the
   * previous frame at reduced opacity, with no layout jump or flash. Failure is not a chart
   * state: the app reports errors, and a chart shows only data, never network status.
   */
  loading?: boolean
  /**
   * The locale `Intl` formats with. When omitted, the runtime's own resolved locale applies.
   */
  locale?: string
  /**
   * Point dots of at least 8px with a 2px surface ring, a second channel for CVD and print.
   */
  markers?: boolean
  /**
   * The tier's message catalog. When omitted, the generic English defaults apply. A localized
   * host passes its own, the same object to every chart on the screen.
   */
  messages?: ChartMessages
  /**
   * Enables the range brush, for a `time` or `linear` x only, because a band has no continuum.
   * The brush only reports a committed range to app state and never filters the chart itself;
   * `FilterBar` owns and displays the range. It passes ISO strings for `time` and numbers for
   * `linear`, and fires on commit only.
   */
  onBrushEnd?: (range: [number, number] | [string, string]) => void
  /**
   * Called with the row at the reading position, on Enter, Space or click.
   */
  onSelect?: (selection: {
    index: number
    datum: Readonly<Record<string, string | number | null>>
  }) => void
  /**
   * The series to draw, 1–8. A ninth gets a dev-warning about folding into "Other", never a
   * generated hue, because the wheel has eight seats.
   */
  series: readonly ChartSeries[]
  /**
   * Frame height, from `--pm-chart-height-*`. The frame never nests a scroll region.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Syncs the reading position across sibling charts through a module-scope registry, with no
   * provider. The broadcast is the **x-domain value**, never the row index, and each receiver
   * maps it through its own scale. Works for a `time` or `linear` x only, like the brush. Escape
   * or blur clears the whole group.
   */
  syncId?: string
  /**
   * Tooltip configuration, on with `'dot'` by default. `false`, for print and report surfaces,
   * removes only the visual layer.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * `area` adds a light wash of the series hue (about 10% alpha) under the line.
   */
  variant?: 'line' | 'area'
  x: ChartXAxis
  /**
   * Y axis configuration. The axis renders by default.
   */
  y?: ChartYAxis
}

/** A line chart for change over time. */
export default function LineChart(given: LineChartProps): JSX.Element {
  const props = mergeProps(
    {
      variant: 'line',
      markers: false,
      curve: 'monotone',
      size: 'md',
      tooltip: (() => ({}))(),
      loading: false,
      messages: (() => DEFAULT_RANGE_MESSAGES)(),
    } as Defaults<
      LineChartProps,
      'variant' | 'markers' | 'curve' | 'size' | 'tooltip' | 'loading' | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const box = createCell(UNMEASURED)
    const reading = createCell(createReading({ count: 0, seriesStart: null }))
    const position = createCell(readingRest(null))
    const hidden = createCell(new Set<string>())
    const twinOpen = createCell(false)
    const warningLog = createCell(createWarningLog())
    const brush = createCell(
      createBrush({ enabled: false, count: 0, positions: [], onCommit: () => undefined }),
    )
    const brushed = createCell(brush.value.state())
    const sync = createCell(createSyncMember((value) => receive.value(value)))
    const receiving = createCell(false)
    const frame = elementRef<HTMLElement>()
    const plot = elementRef<HTMLElement>()
    const input = createDerived(() => ({
      data: props.data,
      series: props.series,
      x: props.x,
      y: props.y,
      variant: props.variant,
      markers: props.markers,
      curve: props.curve,
      emphasis: props.emphasis,
      baseline: props.baseline,
      annotations: props.annotations,
      label: props.label,
      locale: props.locale,
      messages: props.messages,
      tooltip: props.tooltip,
      loading: props.loading,
      selectable: props.onSelect !== undefined,
      brushable: props.onBrushEnd !== undefined,
      syncId: props.syncId,
      hidden: hidden.value,
      box: box.value,
    }))
    const model = createDerived(() => lineChartModel(input.value))
    const view = createDerived(() => readingView(position.value, props.data.length))
    const readout = createDerived(() => lineChartReadout(input.value, model.value, view.value))
    const walk = createDerived(() => ({ count: props.data.length }))
    const rangeSpan = createDerived(() =>
      brushed.value === null ? null : brushSpan(model.value, brush.value.state(props.data.length)),
    )
    const rangeDrawing = createDerived(() =>
      rangeSpan.value === null
        ? null
        : brushDrawing(rangeSpan.value.from, rangeSpan.value.to, rangeSpan.value.height),
    )
    const commit = createDerived(() => (anchor: number, edge: number) => {
      const values = brushValues(input.value, model.value, anchor, edge)
      if (values !== null) props.onBrushEnd?.(values)
    })
    const updateBrush = createDerived(
      () => () =>
        brush.value.update({
          enabled: model.value.brushOn,
          count: props.data.length,
          positions: model.value.positions,
          onCommit: commit.value,
        }),
    )
    const send = createDerived(() => (index: number | null) => {
      if (receiving.value) return
      const value = syncValueAt(model.value, index)
      if (value !== undefined) sync.value.broadcast(value)
    })
    const receive = createDerived(() => (value: number | null) => {
      receiving.value = true
      const at = syncIndexOf(model.value, value)
      if (at !== undefined) reading.value.moveTo(at)
      receiving.value = false
    })
    const activate = createDerived(() => () => {
      const selected = lineChartSelection(input.value, model.value, reading.value.now())
      if (selected !== null) props.onSelect?.(selected)
    })
    const onKey = createDerived(() => (event: KeyboardEvent) => {
      updateBrush.value()
      if (brush.value.key(event.key, event.shiftKey, reading.value)) {
        event.preventDefault()
        return
      }
      if (props.onSelect !== undefined && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault()
        activate.value()
        return
      }
      reading.value.update(walk.value)
      if (reading.value.key(event.key)) event.preventDefault()
    })
    const onPress = createDerived(() => (event: PointerEvent) => {
      if (!model.value.brushOn) return
      updateBrush.value()
      const rect = (event.currentTarget as Element).getBoundingClientRect()
      brush.value.pointerDown(event.clientX - rect.left)
      try {
        ;(event.currentTarget as Element).setPointerCapture(event.pointerId)
      } catch {
        /* a synthetic pointer has nothing to capture; the brush still works */
      }
    })
    const onPointer = createDerived(() => (event: PointerEvent) => {
      if (model.value.plot === null) return
      updateBrush.value()
      const rect = (event.currentTarget as Element).getBoundingClientRect()
      const px = event.clientX - rect.left
      reading.value.moveTo(nearestIndex(model.value.positions, px))
      brush.value.pointerMove(px)
    })
    const onClick = createDerived(() => () => {
      if (brush.value.consumeClick()) return
      activate.value()
    })
    const onLeave = createDerived(() => () => {
      brush.value.blur()
      reading.value.clear()
    })
    const marks = createDerived(() => ({
      walk: walk.value,
      input: input.value,
      model: model.value,
      readout: lineChartReadout,
      selection: lineChartSelection,
    }))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [plot.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      reading.value.subscribe((now) => {
        position.value = now
      })
    }
    onMount(effect2)
    const effect3 = () => {
      warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
    }
    watchEffect(
      createMemo(() => model.value.warnings.join('\n')),
      effect3,
      true,
    )
    const effect4 = () => {
      brush.value.subscribe(() => {
        brushed.value = brush.value.state()
      })
    }
    onMount(effect4)
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      sync.value.join(model.value.syncGroup, plot.value)
      release5 = () => {
        sync.value.leave()
      }
    }
    watchEffect(
      createMemo(() => model.value.syncGroup),
      effect5,
      true,
    )
    onCleanup(() => release5?.())
    const effect6 = () => {
      reading.value.subscribe((now, was) => {
        if (now.index !== was.index) send.value(now.index)
      })
    }
    onMount(effect6)
    let release7: (() => void) | undefined
    const effect7 = () => {
      release7?.()
      const ran =
        !(props.onSelect !== undefined) && !model.value.legend && !model.value.brushOn
          ? () => {}
          : agentMember({
              member: 'LineChart',
              element: () => frame.value,
              state: () => ({
                items: props.onSelect !== undefined ? chartMarks(marks.value, reading.value) : [],
                position: chartPosition(marks.value, reading.value),
                count: walk.value.count,
                series: chartSeries(frame.value, chartLegend.key, model.value.painted),
                hidden: chartHiddenSeries(frame.value, chartLegend.key, model.value.painted),
                'range-start': chartRange(marks.value, brush.value).start,
                'range-end': chartRange(marks.value, brush.value).end,
              }),
              actions: {
                read: {
                  argument: 'number',
                  run: (value) => readChartPosition(marks.value, value, reading.value),
                },
                choose: {
                  argument: 'id',
                  among: 'items',
                  run: (value) =>
                    chooseChartMark(marks.value, value, reading.value, activate.value),
                },
                toggle: {
                  argument: 'id',
                  among: 'series',
                  run: (value) =>
                    toggleChartSeries(frame.value, chartLegend.key, model.value.painted, value),
                },
                brush: {
                  argument: 'number',
                  run: (value) =>
                    (() => {
                      updateBrush.value()
                      brushChartRange(marks.value, value, brush.value, reading.value)
                    })(),
                },
              },
            })
      release7 = () => {
        ran()
      }
    }
    onMount(effect7)
    onCleanup(() => release7?.())
    return (
      <figure
        class={chartFrame.frame}
        data-size={props.size}
        data-state={model.value.state}
        data-position={view.value.active ? view.value.index : undefined}
        aria-label={props.label}
        data-member="line-chart"
        ref={frame.attach}
      >
        {/* region */}
        <div class={chartFrame.region}>
          {/* y axis */}
          <div class={chartFrame.yAxis}>
            {model.value.axes?.y !== undefined ? (
              <div class={chartAxis.axis} data-orientation="y" aria-hidden="true">
                <Each of={model.value.axes?.y ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ top: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
          {/* plot */}
          <div class={chartFrame.plot} ref={plot.attach}>
            {model.value.state === 'empty' ? (
              <div class={chartFrame.empty}>
                <span>{props.messages.empty}</span>
              </div>
            ) : (
              <div
                class={styles.surface}
                tabindex="0"
                role="img"
                aria-label={props.label}
                onkeydown={($event: KeyboardEvent) => onKey.value($event)}
                onclick={() => onClick.value()}
                onpointerdown={($event: PointerEvent) => onPress.value($event)}
                onpointermove={($event: PointerEvent) => onPointer.value($event)}
                onpointerup={() => brush.value.pointerUp()}
                onpointerleave={() => reading.value.clear()}
                onblur={() => onLeave.value()}
              >
                {model.value.plot !== null ? (
                  <svg
                    class={styles.marks}
                    data-variant={props.variant}
                    width={model.value.plot?.width}
                    height={model.value.plot?.height}
                    aria-hidden="true"
                    {...{ focusable: 'false' }}
                  >
                    {/* grid */}
                    <g class={styles.grid}>
                      <Each of={model.value.plot?.grid ?? []} by={(line) => line.key} renew>
                        {(line) => <path d={line.d} />}
                      </Each>
                    </g>
                    {(model.value.plot?.zeroRule ?? null) !== null ? (
                      <path class={styles.zero} d={model.value.plot?.zeroRule ?? undefined} />
                    ) : null}
                    {rangeDrawing.value !== null ? (
                      <g class={chartBrush.brush}>
                        <rect
                          class={chartBrush.range}
                          x={rangeDrawing.value?.x}
                          y={0}
                          width={rangeDrawing.value?.width}
                          height={rangeDrawing.value?.height}
                        />
                        <path class={chartBrush.edge} d={rangeDrawing.value?.near} />
                        <path class={chartBrush.edge} d={rangeDrawing.value?.far} />
                      </g>
                    ) : null}
                    {(model.value.plot?.wash ?? []).length > 0 ? (
                      <g class={chartNotes.washes}>
                        <Each of={model.value.plot?.wash ?? []} by={(span) => span.key} renew>
                          {(span) => (
                            <rect
                              class={chartNotes.span}
                              x={span.x}
                              y={span.y}
                              width={span.width}
                              height={span.height}
                            />
                          )}
                        </Each>
                      </g>
                    ) : null}
                    {(model.value.plot?.ink ?? null) !== null ? (
                      <g class={chartNotes.ink}>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.spans ?? []}
                          by={(span) => span.key}
                          renew
                        >
                          {(span) => (
                            <g>
                              <path class={chartNotes.edge} d={span.from} />
                              <path class={chartNotes.edge} d={span.to} />
                            </g>
                          )}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.rules ?? []}
                          by={(rule) => rule.key}
                          renew
                        >
                          {(rule) => <path class={chartNotes.rule} d={rule.d} />}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.marks ?? []}
                          by={(mark) => mark.key}
                          renew
                        >
                          {(mark) => (
                            <circle class={chartNotes.mark} cx={mark.cx} cy={mark.cy} r={mark.r} />
                          )}
                        </Each>
                        <Each
                          of={(model.value.plot?.ink ?? null)?.labels ?? []}
                          by={(note) => note.key}
                          renew
                        >
                          {(note) => (
                            <text
                              class={chartNotes.label}
                              x={note.x}
                              y={note.y}
                              text-anchor={note.anchor}
                            >
                              {note.text}
                            </text>
                          )}
                        </Each>
                      </g>
                    ) : null}
                    {/* strokes */}
                    <g class={styles.strokes}>
                      <Each of={model.value.plot?.strokes ?? []} by={(stroke) => stroke.key} renew>
                        {(stroke) => (
                          <g style={{ '--pm-chart-mark': stroke.paint }}>
                            {stroke.wash !== null ? (
                              <path class={styles.wash} d={stroke.wash} />
                            ) : null}
                            <path class={styles.line} d={stroke.line} />
                            <Each of={stroke.markers} by={(marker) => marker.key} renew>
                              {(marker) => (
                                <circle
                                  class={styles.marker}
                                  cx={marker.cx}
                                  cy={marker.cy}
                                  r={marker.r}
                                  data-active={view.value.index === marker.index ? '' : undefined}
                                />
                              )}
                            </Each>
                          </g>
                        )}
                      </Each>
                    </g>
                    {readout.value.crosshair !== null ? (
                      <path class={styles.crosshair} d={readout.value.crosshair} />
                    ) : null}
                    <Each of={model.value.plot?.endLabels ?? []} by={(end) => end.key} renew>
                      {(end) => (
                        <text class={styles.endLabel} x={end.x} y={end.y} text-anchor="end">
                          {end.text}
                        </text>
                      )}
                    </Each>
                  </svg>
                ) : null}
              </div>
            )}
            {readout.value.tooltip !== null ? (
              <div
                class={chartTooltip.tooltip}
                style={{
                  '--pm-chart-tip-x': `${readout.value.tooltip?.x}px`,
                  '--pm-chart-tip-y': `${readout.value.tooltip?.y}px`,
                }}
                data-indicator={readout.value.tooltip?.indicator}
                data-side={readout.value.tooltip?.side}
                aria-hidden="true"
              >
                {readout.value.tooltip?.header !== undefined ? (
                  <p class={chartTooltip.header}>{readout.value.tooltip?.header}</p>
                ) : null}
                <ul class={chartTooltip.rows}>
                  <Each of={readout.value.tooltip?.rows ?? []} by={(row) => row.key} renew>
                    {(row) => (
                      <li class={chartTooltip.row}>
                        <span class={chartTooltip.key} style={{ '--pm-chart-key': row.paint }} />
                        <span class={chartTooltip.value}>{row.value}</span>
                        <span class={chartTooltip.label}>{row.label}</span>
                      </li>
                    )}
                  </Each>
                </ul>
              </div>
            ) : null}
          </div>
          {/* x axis */}
          <div class={chartFrame.xAxis}>
            {model.value.axes?.x !== undefined ? (
              <div class={chartAxis.axis} data-orientation="x" aria-hidden="true">
                <Each of={model.value.axes?.x ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ left: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
        </div>
        {model.value.legend ? (
          model.value.painted.length > 0 ? (
            <ul class={styles.legend} data-key-shape="line">
              <Each of={model.value.painted} by={(entry) => entry.key} renew>
                {(entry) => (
                  <li class={chartLegend.item}>
                    <button
                      class={chartLegend.key}
                      type="button"
                      aria-pressed={hidden.value.has(entry.key) ? 'false' : 'true'}
                      onclick={() => (hidden.value = toggleSeries(hidden.value, entry.key))}
                    >
                      <span
                        class={chartLegend.swatch}
                        style={{ '--pm-chart-key': entry.paint }}
                        aria-hidden="true"
                      />
                      {entry.icon !== undefined ? (
                        <span class={chartLegend.glyph}>
                          <Icon name={entry.icon} size="sm" />
                        </span>
                      ) : null}
                      <span class={chartLegend.label}>{entry.label}</span>
                    </button>
                  </li>
                )}
              </Each>
            </ul>
          ) : null
        ) : null}
        {/* summary */}
        <span class={a11y.visuallyHidden}>{model.value.summary}</span>
        {/* twin */}
        <div class={chartTwin.twin} data-state={twinOpen.value ? 'open' : 'closed'}>
          <div class={chartTwin.toggle}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="table"
              iconOnly={true}
              label={
                twinOpen.value
                  ? props.messages.hideTable(props.label)
                  : props.messages.showTable(props.label)
              }
              onClick={() => (twinOpen.value = !twinOpen.value)}
            />
          </div>
          {twinOpen.value ? (
            <div class={chartTwin.table}>
              <Table
                label={props.messages.tableLabel(props.label)}
                caption={props.messages.tableLabel(props.label)}
              >
                <TableHead>
                  <TableRow>
                    <Each of={model.value.twin.columns} by={(column) => column.key} renew>
                      {(column) => (
                        <TableHeader numeric={column.numeric}>{column.label}</TableHeader>
                      )}
                    </Each>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <Each of={model.value.twin.rows} by={(_row, line) => line} renew>
                    {(row) => (
                      <TableRow>
                        <Each
                          of={row}
                          by={(_cell, cellIndex) =>
                            model.value.twin.columns[cellIndex]?.key ?? cellIndex
                          }
                          renew
                        >
                          {(cell, cellIndex) => (
                            <TableCell numeric={model.value.twin.columns[cellIndex()]?.numeric}>
                              {cell === '' ? '—' : cell}
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                    )}
                  </Each>
                </TableBody>
              </Table>
            </div>
          ) : null}
        </div>
        {/* live region */}
        <span class={a11y.visuallyHidden}>
          <div aria-live="polite" aria-atomic="true">
            {readout.value.announcement}
          </div>
        </span>
      </figure>
    )
  })
}
